def label_text(parcel: Parcel, to: Address, parcels_total: int, weight_g: int | None = None) -> str:
    """Label for one parcel: address, order/parcel line, contents, and weight when known.

    The weight is shown in pounds for US destinations (the unit those customers expect) and in
    the shop's standard kilograms everywhere else, both via ``format_weight`` so labels and
    packing slips agree."""
    lines = [format_address(to), "", f"Order {parcel.order_id}  parcel {parcel.number}/{parcels_total}"]
    if weight_g is not None:
        unit = "lb" if to.country.strip().upper() == "US" else "kg"
        lines.append(f"Weight: {format_weight(weight_g, unit)}")
    lines += [f"{label_code(sku)} x{qty}" for sku, qty in parcel.items]
    return "\n".join(lines)
